<template>
  <div class="text-center">
<div class="badge badge-xl badge-success">
{{ fuelRatio(30,20,'vehicle',120) }}
</div>
  </div>

<br/>

<!-- <button class="btn btn-primary"
 data-bs-toggle="modal" data-bs-target="#bulk-filling"
>Add</button> -->

                 <div class="modal fade mymodal" id="bulk-filling" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">Bulk Fuel Addition Form</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-bulk-form" ></button>
      </div>

<form @submit.prevent="addBulk()">

    <div class="modal-body" >
       <div class="row me-5">
  <div class="col-md-3">
    <label class="form-label">Order No#</label>
    <input type="number" class="form-control" placeholder="Order ID" required v-model="order_id">
  </div>

    <div class="col-md-3">
    <label class="form-label">Quantity</label>
    <input type="number" class="form-control" step="any" placeholder="Quantity" required v-model="quantity">
  </div>

    <div class="col-md-3">
    <label class="form-label">Purchase Rate</label>
    <input type="number" class="form-control"  step="any" placeholder="Rate" required v-model="rate">
  </div>

    <div class="col-md-3">
    <label class="form-label">Issued Date</label>
    <input type="date" class="form-control" placeholder="date" required v-model="date">
  </div>

</div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger me-2" data-bs-dismiss="modal">Close</button>
       <button class="btn btn-primary" type="submit" :disabled="loading">
          <span v-if="loading" v-html="loadingSpinner()"></span>
          <span v-else>Submit</span>
        </button>
    </div>
</form>

    </div>
  </div>

</div>




</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
import Payroll from '../hr/employees/payroll.vue';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

   const fuelRatio = inject('fuelRatio')


const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    entryId : String
});


const showError = inject('showError')
const showMessage = inject('showMessage')
const waitIndicator = inject('waitIndicator')
const loadingSpinner = inject('loadingSpinner')

const order_id = ref('')
const date = ref('')
const quantity = ref('')
const rate = ref('')

const loading = ref(false)

const clearForm = ()=>{
 order_id.value = '',
 quantity.value = '',
 rate.value = '',
 date.value  = '',
 document.getElementById('close-bulk-form').click()
}

const addBulk = async()=>{
  loading.value = true
  const payload = {
    source : 'LPO',
    source_id : order_id.value,
    // entry_id : props.entryId,
    entry_id : 2077,
    quantity : quantity.value,
    rate : rate.value,
    date : date.value
  }
  try{
    const response = await axiosInstance.post(`entry-items`,payload)
    showMessage('Bulk Added!')
    clearForm()
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
    loading.value = false
  }
}


    onMounted(async() => {

    })

</script>




